import {campusMapImage,loadCampusBase} from './campus-map.js?v=base-upload-20261111';
import {uploadServiceURL} from './field-config.js';
export function mountCampusBaseUpload({getUser,isAdmin}){
 let mounted=false;
 async function mount(){const article=document.querySelector('[data-document="campus-ecology-map"]');if(!article||mounted)return;mounted=true;
 const section=document.createElement('section');section.id='campus-base-upload';section.innerHTML='<h3>校園俯視圖上傳區</h3><p>預設使用 v3。選擇新底圖後先預覽，發布後更新所有校園俯視圖。此處僅顯示無標籤底圖；導覽頁的區域名稱與斜坡圖層仍保留。</p><div style="position:relative"><img data-preview alt="目前校園俯視底圖（無標籤）" style="display:block;width:100%"></div><label>選擇替換底圖<input type="file" accept="image/png,image/jpeg,image/webp"></label><p>請使用與 v3 相同的範圍、方向及 1448:1088 比例，圖片不可已有區域文字。圖片會轉為 JPEG；原圖請自行備份。</p><label><input type="checkbox"> 我已核對底圖範圍與方向，確認可以公開</label><button data-publish type="button" disabled>發布新底圖</button> <button data-cancel type="button">取消預覽</button><p role="status"></p>';
 const style=document.createElement('style');style.textContent='[data-document="campus-ecology-map"]{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1fr);gap:16px}[data-document="campus-ecology-map"]> *{grid-column:1/-1}[data-document="campus-ecology-map"]>a[aria-label]{grid-column:1;grid-row:4}#campus-base-upload{grid-column:2;grid-row:4;min-width:0;padding:16px;border:1px solid #cad7c3;border-radius:8px}#campus-base-upload h3{margin-top:0}@media(max-width:800px){[data-document="campus-ecology-map"]{display:block}#campus-base-upload{margin-top:16px}}';section.append(style);article.append(section);
 const preview=section.querySelector('[data-preview]'),file=section.querySelector('input[type=file]'),confirm=section.querySelector('input[type=checkbox]'),publish=section.querySelector('[data-publish]'),cancel=section.querySelector('[data-cancel]'),status=section.querySelector('[role=status]');preview.src=campusMapImage;let original,pending=null,busy=false,selection=0;
 function update(){file.disabled=confirm.disabled=cancel.disabled=busy||!isAdmin();publish.disabled=busy||!isAdmin()||!pending||!confirm.checked;}
 try{original=await loadCampusBase();preview.src=original.url;}catch(e){status.textContent=e.message;update();return;}
 confirm.onchange=update;document.addEventListener('teacher-context-change',()=>{confirm.checked=false;update()});
 file.onchange=async()=>{const picked=file.files?.[0],id=++selection;pending=null;confirm.checked=false;update();if(!picked)return;if(!isAdmin())return;status.textContent='正在讀取與檢查圖片…';try{if(picked.size>20000000)throw Error('請選擇 20 MB 以下圖片');const url=URL.createObjectURL(picked);let image;try{image=await new Promise((resolve,reject)=>{const img=new Image();img.onload=()=>resolve(img);img.onerror=()=>reject(Error('無法讀取圖片，請使用 PNG、JPEG 或 WebP'));img.src=url;});}finally{URL.revokeObjectURL(url)}if(Math.abs(image.naturalWidth/image.naturalHeight-1448/1088)>.005)throw Error('圖片比例與 v3 不同，請先裁切為 1448:1088，避免區域標籤錯位');const canvas=document.createElement('canvas');canvas.width=1448;canvas.height=1088;const context=canvas.getContext('2d');context.fillStyle='#fff';context.fillRect(0,0,1448,1088);context.drawImage(image,0,0,1448,1088);const encoded=canvas.toDataURL('image/jpeg',.92);if(encoded.length>2100000)throw Error('轉換後圖片過大，請簡化圖片後重試');if(id!==selection)return;pending=encoded.split(',')[1];preview.src=encoded;status.textContent='預覽尚未發布。請核對底圖範圍與方向，勾選確認後發布。';}catch(e){if(id===selection){preview.src=original.url;status.textContent=e.message;}}finally{update()}};
 cancel.onclick=()=>{selection++;pending=null;file.value='';confirm.checked=false;preview.src=original.url;status.textContent='已恢復目前發布底圖。';update();};
 publish.onclick=async()=>{if(busy||!pending||!confirm.checked||!isAdmin())return;busy=true;update();status.textContent='正在提交新底圖…';try{const r=await fetch(uploadServiceURL+'/campus/base',{method:'POST',headers:{Authorization:'Bearer '+await getUser().getIdToken(),'Content-Type':'application/json'},body:JSON.stringify({id:crypto.randomUUID(),image:pending,previous:original})});const result=await r.json();if(!r.ok)throw Error(result.error||'發布失敗');pending=null;confirm.checked=false;status.textContent='已提交 '+result.commit.slice(0,7)+'，部署完成後請重新整理頁面。';}catch(e){status.textContent=e.message+'；圖片預覽仍保留，可重試。';}finally{busy=false;update()}};update();
 }
 document.addEventListener('environment-reference-ready',mount);void mount();
}
